### 9. How Runner Is Used From Main Entry Point

**File**: `/src/main.rs`

```rust
fn main() -> ExitCode {
    let cli = Cli::parse();
    init_tracing(cli.debug);

    let output_mode = if cli.quiet { OutputMode::Quiet }
                      else if cli.verbose { OutputMode::Verbose }
                      else { OutputMode::Normal };

    let is_interactive = match &cli.command {
        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
        _ => !is_ci(),
    };

    // Create UI based on interactivity
    let mut ui = create_ui(is_interactive, output_mode);  // ← Creates either TerminalUI or NonInteractiveUI

    let dispatcher = CommandDispatcher::new(project_root);

    match dispatcher.dispatch(&cli, ui.as_mut()) {  // ← Passes UI to dispatcher
        Ok(result) => ExitCode::from(result.exit_code as u8),
        Err(e) => {
            ui.error(&format!("Error: {}", e));
            ExitCode::from(1)
        }
    }
}
```

