impl Command for RunCommand {
    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
        // Load config
        let config = load_merged_config(&self.project_root)?;

        // Show header
        ui.show_run_header(app_name, &workflow_name, step_count, VERSION);

        // Resolve steps and environment
        let steps = self.resolve_steps(&config, Some(&env_name))?;

        // Create runner
        let runner = WorkflowRunner::new(&config, steps);

        // Run the workflow with UI
        let result = runner.run_with_ui(
            &options,
            &ctx,
            &global_env,
            &self.project_root,
            workflow_non_interactive,
            &step_overrides,
            Some(&mut gap_checker),
            ui,  // ← Passes UI to runner
        )?;

        // Show final summary
        ui.show_run_summary(&summary);

        if result.success {
            ui.show_hint(hints::after_successful_run());
            Ok(CommandResult::success())
        } else {
            ui.show_hint(&hints::after_failed_run(&failed_steps));
            Ok(CommandResult::failure(1))
        }
    }
}
