### 5. TerminalUI Implementation

**File**: `/src/ui/terminal.rs`

Concrete implementation that uses `console::Term` and theme system:

```rust
pub struct TerminalUI {
    term: Term,
    theme: BivvyTheme,
    mode: OutputMode,
}

impl UserInterface for TerminalUI {
    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
        if self.mode.shows_spinners() {
            Box::new(ProgressSpinner::new(message))  // ← indicatif spinner
        } else {
            Box::new(ProgressSpinner::hidden())
        }
    }

    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
        prompt_user(prompt, &self.term)  // ← dialoguer prompt
    }

    // show_run_header, show_workflow_progress, show_error_block, show_run_summary
    // all use theme styling and formatting
}

pub fn create_ui(interactive: bool, mode: OutputMode) -> Box<dyn UserInterface> {
    if interactive && Term::stdout().is_term() {
        Box::new(TerminalUI::new(mode))
    } else {
        Box::new(NonInteractiveUI::new(mode))
    }
}
```

