            println!("  {}", message);  // Just print, no animation
        }
        Box::new(NoopSpinner { indent: 0 })  // No-op spinner
    }

    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
        // Check BIVVY_PROMPT_{KEY} env var, fall back to default
        let env_key = format!("BIVVY_PROMPT_{}", prompt.key.to_uppercase());
        if let Some(value) = self.env_overrides.get(&env_key) {
            // Return environment value
        } else if let Some(default) = &prompt.default {
            // Use default
        } else {
            // Error: can't prompt
        }
    }
}

struct NoopSpinner { indent: usize }  // Does nothing
impl SpinnerHandle for NoopSpinner { /* no-op implementations */ }
