### 8. The Runner Module

**File**: `/src/runner/workflow.rs`

Orchestrates workflow execution with direct UI interaction:

```rust
pub struct WorkflowRunner<'a> {
    config: &'a BivvyConfig,
    steps: HashMap<String, ResolvedStep>,
}

impl<'a> WorkflowRunner<'a> {
    pub fn run_with_ui(
        &self,
        options: &RunOptions,
        context: &InterpolationContext,
        global_env: &HashMap<String, String>,
        project_root: &Path,
        workflow_non_interactive: bool,
        step_overrides: &HashMap<String, StepOverride>,
        mut gap_checker: Option<&mut GapChecker<'_>>,
        ui: &mut dyn UserInterface,  // ← Takes mutable UserInterface reference
    ) -> Result<WorkflowResult> {
        // ... builds dependency graph, resolves step order

        for (index, step_name) in steps_to_run.iter().enumerate() {
            let step = self.steps.get(step_name)?;

            // Display step with formatting
            ui.message(&step_display);
            ui.show_workflow_progress(index + 1, total, start.elapsed());

            // Handle prompts for already-complete steps
            if interactive && effective_prompt_if_complete {
                let prompt = Prompt {
                    key: format!("rerun_{}", step_name),
                    question: format!("Already complete. Re-run {}?", step_display),
                    prompt_type: PromptType::Select {  // Create a prompt
                        options: vec![/* ... */],
                    },
                    default: Some("no".to_string()),
                };

                let answer = ui.prompt(&prompt)?;  // ← Directly calls UI prompt
                // Handle answer...
            }

            // Execute step with spinner
            let mut spinner = ui.start_spinner(&format!("Running {}", step_name));
            let result = execute_step(...)?;
            spinner.finish_success("Success");  // ← Updates spinner

            // Show workflow progress
            ui.show_workflow_progress(index + 1, total, start.elapsed());
        }

        // Show final summary
        ui.show_run_summary(&summary);  // ← Shows structured summary
    }
}
```

---

### 9. How Runner Is Used From Main Entry Point

**File**: `/src/main.rs`

```rust
fn main() -> ExitCode {
    let cli = Cli::parse();
    init_tracing(cli.debug);

    let output_mode = if cli.quiet { OutputMode::Quiet }
                      else if cli.verbose { OutputMode::Verbose }
                      else { OutputMode::Normal };

    let is_interactive = match &cli.command {
        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
        _ => !is_ci(),
    };

    // Create UI based on interactivity
    let mut ui = create_ui(is_interactive, output_mode);  // ← Creates either TerminalUI or NonInteractiveUI

    let dispatcher = CommandDispatcher::new(project_root);

    match dispatcher.dispatch(&cli, ui.as_mut()) {  // ← Passes UI to dispatcher
        Ok(result) => ExitCode::from(result.exit_code as u8),
        Err(e) => {
            ui.error(&format!("Error: {}", e));
            ExitCode::from(1)
        }
    }
}
```

**File**: `/src/cli/commands/run.rs` (RunCommand.execute)

```rust
impl Command for RunCommand {
    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
        // Load config
        let config = load_merged_config(&self.project_root)?;

        // Show header
        ui.show_run_header(app_name, &workflow_name, step_count, VERSION);

        // Resolve steps and environment
        let steps = self.resolve_steps(&config, Some(&env_name))?;

        // Create runner
        let runner = WorkflowRunner::new(&config, steps);

        // Run the workflow with UI
        let result = runner.run_with_ui(
            &options,
            &ctx,
            &global_env,
            &self.project_root,
            workflow_non_interactive,
            &step_overrides,
            Some(&mut gap_checker),
            ui,  // ← Passes UI to runner
        )?;

        // Show final summary
        ui.show_run_summary(&summary);

        if result.success {
            ui.show_hint(hints::after_successful_run());
            Ok(CommandResult::success())
        } else {
            ui.show_hint(&hints::after_failed_run(&failed_steps));
            Ok(CommandResult::failure(1))
        }
    }
}
```

