326→        for skip_name in &env_skipped {
327→            ui.message(&format!(
328→                "    {}",
329→                theme.format_skipped(&format!(
330→                    "{} skipped (not in {} environment)",
331→                    skip_name,
332→                    options.active_environment.as_deref().unwrap_or("unknown")
333→                ))
334→            ));
335→        }
336→
337→        let interactive = ui.is_interactive() && !workflow_non_interactive;
338→        let installer_ctx = installer::default_context();
339→
340→        let mut results = Vec::new();
341→        let mut all_success = true;
342→        let mut failed_steps: HashSet<String> = HashSet::new();
343→        let mut workflow_aborted = false;
344→
345→        for (index, step_name) in steps_to_run.iter().enumerate() {
346→            let step =
347→                self.steps
348→                    .get(step_name)
349→                    .ok_or_else(|| BivvyError::ConfigValidationError {
350→                        message: format!("Step '{}' not found in resolved steps", step_name),
351→                    })?;
352→
353→            // Blank line between steps
354→            if index > 0 {
355→                ui.message("");
356→            }
357→
358→            // Format step display with numbering: "[1/7] name — title" or "[1/7] name"
359→            let step_number = format!("[{}/{}]", index + 1, total);
360→            let step_display = if *step_name == step.title {
361→                format!(
362→                    "{} {}",
363→                    theme.step_number.apply_to(&step_number),
364→                    theme.step_title.apply_to(step_name)
365→                )
366→            } else {
367→                format!(
368→                    "{} {} {} {}",
369→                    theme.step_number.apply_to(&step_number),
370→                    theme.step_title.apply_to(step_name),
371→                    theme.dim.apply_to("—"),
372→                    theme.dim.apply_to(&step.title)
373→                )
374→            };
375→
376→            // Check if any dependency failed
377→            if step.depends_on.iter().any(|dep| failed_steps.contains(dep)) {
378→                ui.message(&step_display);
379→                ui.message(&format!(
380→                    "    {}",
381→                    StatusKind::Blocked.format(&theme, "Blocked (dependency failed)")
382→                ));
383→                ui.show_workflow_progress(index + 1, total, start.elapsed());
384→                all_success = false;
385→                failed_steps.insert(step_name.clone());
386→                continue;
387→            }
388→
389→            // Check requirement gaps before proceeding
390→            if let Some(ref mut checker) = gap_checker {
391→                let provided = if options.provided_requirements.is_empty() {
392→                    None
393→                } else {
394→                    Some(&options.provided_requirements)
395→                };
396→                let gaps = checker.check_step(step, provided);
397→                if !gaps.is_empty() {
398→                    let can_proceed =
399→                        installer::handle_gaps(&gaps, checker, ui, interactive, &installer_ctx)?;
400→                    if !can_proceed {
401→                        ui.message(&step_display);
402→                        ui.message(&format!(
403→                            "    {}",
404→                            StatusKind::Skipped.format(&theme, "Skipped (requirement not met)")
405→                        ));
406→                        ui.show_workflow_progress(index + 1, total, start.elapsed());
407→                        continue;
408→                    }
409→                }
410→            }
411→
412→            // Resolve effective prompt_if_complete (step-level, possibly overridden)
413→            let effective_prompt_if_complete = step_overrides
414→                .get(step_name)
415→                .and_then(|o| o.prompt_if_complete)
416→                .unwrap_or(step.prompt_if_complete);
417→
418→            let mut needs_force = options.force.contains(step_name);
419→            let mut already_prompted = false;
420→            let mut had_prompt = false;
421→
422→            // Check if already complete (unless forced)
423→            if !needs_force && !options.dry_run {
424→                if let Some(ref check) = step.completed_check {
425→                    let check_result = run_check(check, project_root);
426→                    if check_result.complete {
427→                        if interactive && effective_prompt_if_complete {
428→                            if step.skippable {
429→                                // Ask if they want to re-run (prompt IS the step header)
430→                                let prompt = Prompt {
431→                                    key: format!("rerun_{}", step_name),
432→                                    question: format!("Already complete. Re-run {}?", step_display),
433→                                    prompt_type: PromptType::Select {
434→                                        options: vec![
435→                                            PromptOption {
436→                                                label: "No (n)".to_string(),
437→                                                value: "no".to_string(),
438→                                            },
439→                                            PromptOption {
440→                                                label: "Yes (y)".to_string(),
441→                                                value: "yes".to_string(),
442→                                            },
443→                                        ],
444→                                    },
445→                                    default: Some("no".to_string()),
446→                                };
447→
448→                                let answer = ui.prompt(&prompt)?;
449→                                if answer.as_string() != "yes" {
450→                                    let reason = check_result.short_description();
451→                                    ui.message(&format!(
452→                                        "    {}",
453→                                        theme.format_skipped(&format!("Skipped ({})", reason))
454→                                    ));
455→                                    results.push(StepResult::skipped(&step.name, check_result));
456→                                    continue;
457→                                }
458→                                // User wants to re-run
459→                                needs_force = true;
460→                                already_prompted = true;
461→                                had_prompt = true;
462→                            } else {
463→                                // Not skippable, inform and re-run
464→                                ui.message(&step_display);
465→                                ui.message("    Re-running (not skippable)");
466→                                needs_force = true;
467→                            }
468→                        } else {
469→                            // Not interactive or prompt_if_complete is false: silently skip
470→                            ui.message(&step_display);
471→                            let reason = check_result.short_description();
472→                            ui.message(&format!(
473→                                "    {}",
474→                                theme.format_skipped(&format!("Skipped ({})", reason))
475→                            ));
476→                            results.push(StepResult::skipped(&step.name, check_result));
477→                            continue;
478→                        }
479→                    }
480→                }
481→            }
482→
483→            // In interactive mode, prompt before running skippable steps
484→            // (skip if already prompted by completed check)
485→            if interactive && step.skippable && !already_prompted {
486→                let prompt = Prompt {
487→                    key: format!("run_{}", step_name),
488→                    question: format!("{}?", step_display),
489→                    prompt_type: PromptType::Select {
490→                        options: vec![
491→                            PromptOption {
492→                                label: "Yes (y)".to_string(),
493→                                value: "yes".to_string(),
494→                            },
495→                            PromptOption {
496→                                label: "No (n)".to_string(),
497→                                value: "no".to_string(),
498→                            },
499→                        ],

  1→//! Progress spinners.
  2→
  3→use indicatif::{ProgressBar, ProgressStyle};
  4→use std::collections::VecDeque;
  5→use std::sync::{Arc, Mutex};
  6→use std::time::Duration;
  7→
  8→use crate::shell::OutputLine;
  9→
 10→use super::theme::BivvyTheme;
 11→use super::SpinnerHandle;
 12→
 13→/// A progress spinner for long-running operations.
 14→pub struct ProgressSpinner {
 15→    bar: ProgressBar,
 16→    indent: usize,
 17→}
 18→
 19→impl ProgressSpinner {
 20→    /// Create a new spinner with a message.
 21→    pub fn new(message: &str) -> Self {
 22→        Self::with_indent(message, 0)
 23→    }
 24→
 25→    /// Create a new spinner with indentation.
 26→    pub fn with_indent(message: &str, indent: usize) -> Self {
 27→        let bar = ProgressBar::new_spinner();
 28→        let prefix = " ".repeat(indent);
 29→        bar.set_style(
 30→            ProgressStyle::default_spinner()
 31→                .tick_chars("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
 32→                .template(&format!("{}{{spinner:.magenta}} {{msg}}", prefix))
 33→                .unwrap(),
 34→        );
 35→        bar.set_message(message.to_string());
 36→        bar.enable_steady_tick(Duration::from_millis(80));
 37→
 38→        Self { bar, indent }
 39→    }
 40→
 41→    /// Create a spinner that doesn't show (for silent mode).
 42→    pub fn hidden() -> Self {
 43→        let bar = ProgressBar::hidden();
 44→        Self { bar, indent: 0 }
 45→    }
 46→
 47→    /// Get a clone of the inner progress bar for use in callbacks.
 48→    ///
 49→    /// This is useful for live output streaming: the cloned bar can be
 50→    /// passed to a callback running on another thread, and `set_message`
 51→    /// calls on it will update the spinner display in real-time.
 52→    pub fn bar_clone(&self) -> ProgressBar {
 53→        self.bar.clone()
 54→    }
 55→}
 56→
 57→impl SpinnerHandle for ProgressSpinner {
 58→    fn set_message(&mut self, msg: &str) {
 59→        self.bar.set_message(msg.to_string());
 60→    }
 61→
 62→    fn finish_success(&mut self, msg: &str) {
 63→        let prefix = " ".repeat(self.indent);
 64→        let theme = BivvyTheme::new();
 65→        self.bar
 66→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 67→        self.bar
 68→            .finish_with_message(format!("{}{}", prefix, theme.format_success(msg)));
 69→    }
 70→
 71→    fn finish_error(&mut self, msg: &str) {
 72→        let prefix = " ".repeat(self.indent);
 73→        let theme = BivvyTheme::new();
 74→        self.bar
 75→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 76→        self.bar
 77→            .finish_with_message(format!("{}{}", prefix, theme.format_error(msg)));
 78→    }
 79→
 80→    fn finish_skipped(&mut self, msg: &str) {
 81→        let prefix = " ".repeat(self.indent);
 82→        let theme = BivvyTheme::new();
 83→        self.bar
 84→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 85→        self.bar
 86→            .finish_with_message(format!("{}{}", prefix, theme.format_skipped(msg)));
 87→    }
 88→
 89→    fn progress_bar(&self) -> Option<ProgressBar> {
 90→        Some(self.bar.clone())
 91→    }
 92→}
 93→
 94→/// Create a step-style spinner.
 95→pub fn step_spinner(step_name: &str, description: &str) -> ProgressSpinner {
 96→    let msg = format!("{} - {}", step_name, description);
 97→    ProgressSpinner::new(&msg)
 98→}
 99→
100→/// Create an output callback that updates a spinner with live output lines.
101→///
102→/// The callback maintains a ring buffer of the last `max_lines` output lines
103→/// and updates the spinner message to show the base message plus those lines.
104→/// This gives users feedback that a command is actually making progress.
105→///
106→/// # Arguments
107→/// * `bar` - A cloned `ProgressBar` from the spinner
108→/// * `base_message` - The primary spinner message (e.g., "Running install_deps...")
109→/// * `indent` - Number of spaces to indent live output lines
110→/// * `max_lines` - Maximum number of live output lines to show (2-3 typical)
111→pub fn live_output_callback(
112→    bar: ProgressBar,
113→    base_message: String,
114→    indent: usize,
115→    max_lines: usize,
116→) -> crate::shell::OutputCallback {
117→    let buffer: Arc<Mutex<VecDeque<String>>> = Arc::new(Mutex::new(VecDeque::new()));
118→    let theme = BivvyTheme::new();
119→
120→    Box::new(move |line: OutputLine| {
121→        let text = match &line {
122→            OutputLine::Stdout(s) => s.trim_end().to_string(),
123→            OutputLine::Stderr(s) => s.trim_end().to_string(),
124→        };
125→
126→        // Skip empty lines
127→        if text.is_empty() {
128→            return;
129→        }
130→
131→        // Truncate long lines for display
132→        let display_text = if text.len() > 72 {
133→            format!("{}...", &text[..69])
134→        } else {
135→            text
136→        };
137→
138→        let mut buf = buffer.lock().unwrap();
139→        buf.push_back(display_text);
140→        while buf.len() > max_lines {
141→            buf.pop_front();
142→        }
143→
144→        // Build multi-line message: base message + indented output lines
145→        let prefix = " ".repeat(indent);
146→        let mut msg = base_message.clone();
147→        for line in buf.iter() {
148→            msg.push('\n');
149→            msg.push_str(&prefix);
150→            msg.push_str(&theme.dim.apply_to(format!("» {}", line)).to_string());
151→        }
152→
153→        bar.set_message(msg);
154→    })
155→}
