/// Format a step header like "[1/7] step_name" or "[1/7] step_name -- title".
/// Returns the formatted string; the caller passes it to `message()` or embeds it in prompts.
fn format_step_header(&self, index: usize, total: usize, name: &str, title: &str) -> String {
    let step_number = format!("[{}/{}]", index + 1, total);
    if name == title {
        format!("{} {}", step_number, name)
    } else {
        format!("{} {} \u{2014} {}", step_number, name, title)
    }
}

/// Format a status message like "Skipped (reason)" or "Blocked (dependency failed)".
/// Returns the formatted string with appropriate icon/styling.
fn format_status(&self, status: StatusKind, message: &str) -> String {
    status.format_plain(message)
}
```

The default implementations use plain text (no colors), which is correct for `MockUI` and as a fallback.

