            .run_with_progress(
                &options,
                &ctx,
                &HashMap::new(),
                temp.path(),
                None,
                |progress| match &progress {
                    RunProgress::StepStarting { name, .. } => {
                        events.push(format!("start:{}", name));
                    }
                    RunProgress::StepFinished { name, .. } => {
                        events.push(format!("finish:{}", name));
                    }
                    RunProgress::StepSkipped { name } => {
                        events.push(format!("skip:{}", name));
                    }
                },
            )
            .unwrap();

