    #[test]
    fn recovery_detail_in_retry() {
        // After successful retry, recovery_detail records the attempt number.
        let temp = TempDir::new().unwrap();
        let marker = temp.path().join("attempt");

        let cmd = format!(
            "if [ -f {m} ]; then exit 0; else touch {m} && exit 1; fi",
